#!/usr/bin/env python3
# Exact finite checker for the conditional interval calculation in task 93.
# No external packages.  A partition is a decreasing tuple of positive parts.

def partitions_of(n, max_part, max_len, cap=None):
    if cap is None:
        cap = max_part
    if n == 0:
        yield ()
        return
    if max_len == 0:
        return
    for a in range(min(cap, max_part, n), 0, -1):
        for tail in partitions_of(n-a, max_part, max_len-1, a):
            yield (a,) + tail

def in_interval(lam, i, j):
    # i^j contained in lam, and lam contained in (i+1)^(j+1).
    return len(lam) <= j+1 and (not lam or lam[0] <= i+1) and all(lam[t] >= i for t in range(j))

def interval_partitions(degree, i, j):
    return sorted(x for x in partitions_of(degree, i+1, j+1) if in_interval(x, i, j))

def C(x, k, i, j):
    y = k-x
    ans = (i+1,)*x + (i,)*(j-x)
    if y:
        ans += (y,)
    return ans

def h1(lam, i, j):
    # All legal one-box extensions inside the interval box.
    padded = list(lam) + [0]*(j+1-len(lam))
    out = set()
    for t in range(j+1):
        z = padded[:]
        z[t] += 1
        if all(z[u] >= z[u+1] for u in range(j)):
            mu = tuple(a for a in z if a)
            if in_interval(mu, i, j):
                out.add(mu)
    return sorted(out)

def det(a):
    # Fraction-free Bareiss determinant, exact over Z.
    a = [row[:] for row in a]
    n = len(a)
    if n == 0:
        return 1
    sign, prev = 1, 1
    for k in range(n-1):
        if a[k][k] == 0:
            sw = next((s for s in range(k+1,n) if a[s][k] != 0), None)
            if sw is None:
                return 0
            a[k], a[sw] = a[sw], a[k]
            sign = -sign
        pivot = a[k][k]
        for r in range(k+1,n):
            for c in range(k+1,n):
                a[r][c] = (a[r][c]*pivot - a[r][k]*a[k][c]) // prev
        prev = pivot
        for r in range(k+1,n):
            a[r][k] = 0
    return sign*a[-1][-1]

tuple_count = 0
level_count = 0
pieri_row_checks = 0
minor_checks = 0
endpoint_checks = 0
for i in range(1,9):
  for j in range(1,9):
    tuple_count += 1
    d, b = i*j, min(i,j)
    for k in range(b+1):
        level_count += 1
        cols = [C(x,k,i,j) for x in range(k+1)]
        assert interval_partitions(d+k,i,j) == sorted(cols), (i,j,k,interval_partitions(d+k,i,j),cols)
        if k == 0:
            continue
        parents = [C(x,k-1,i,j) for x in range(k)]
        assert interval_partitions(d+k-1,i,j) == sorted(parents), (i,j,k)
        rows = []
        for x, parent in enumerate(parents):
            got = h1(parent,i,j)
            expected = sorted([C(x,k,i,j), C(x+1,k,i,j)])
            assert got == expected, (i,j,k,x,parent,got,expected)
            row = [0]*(k+1)
            row[x] = row[x+1] = 1
            rows.append(row)
            pieri_row_checks += 1
        # Delete C_0.  The resulting relation matrix is unitriangular.
        assert det([row[1:] for row in rows]) == 1, (i,j,k,rows)
        minor_checks += 1
        # Explicitly witness C_k-(-1)^k C_0 as an integral row combination.
        coeff = [(-1)**(k-1-t) for t in range(k)]
        witness = [sum(coeff[t]*rows[t][u] for t in range(k)) for u in range(k+1)]
        target = [-(-1)**k] + [0]*(k-1) + [1]
        assert witness == target, (i,j,k,coeff,witness,target)
        endpoint_checks += 1

print('INPUTS: i,j in {1,...,8}; k in {0,...,min(i,j)}')
print('PARAMETER_TUPLES:', tuple_count)
print('DEGREE_LEVELS_CHECKED:', level_count)
print('COMPLETE_H1_ROWS_CHECKED:', pieri_row_checks)
print('UNITRIANGULAR_COMPLEMENTARY_MINORS_CHECKED:', minor_checks)
print('ENDPOINT_SIGN_WITNESSES_CHECKED:', endpoint_checks)
print('IDENTITY_CHECKED: [C_k] = (-1)^k [C_0] in the row-lattice quotient')
print('RESULT: PASS')
